  UH = `Ez az a játék, amely a kitartást jutalmazza, és nem gyengéknek való. Ez minden idők legkeményebb játéka, amit szerettünk.`,
  WH = `Ez a meg nem énekelt hős megérdemli az elismerést kiemelkedő zenei anyagáért. Ez a legebb zenei anyag! `,
